/**
 * The catalogue's data model. Every other layer (build scripts, search,
 * routes, exports) reads icons through these types; nothing about an icon is
 * stored outside `src/catalog`.
 *
 * Authored by people:
 *   src/catalog/icons/<category>/<slug>.svg        the master drawing (outline)
 *   src/catalog/icons/<category>/<slug>.<style>.svg optional hand-drawn style
 *   src/catalog/metadata/<category>.json           IconMeta[] of that category
 *   src/catalog/categories/index.ts                 categories and subcategories
 *
 * Generated by `npm run catalog:index` (src/catalog/registry/generated):
 *   manifest.json, shards/<category>.json, search-index.json, ui-icons.json
 */

export type Locale = 'pt' | 'en'

/** A text in Portuguese (the interface language) and English (aliases, code). */
export interface Localized {
  pt: string
  en: string
}

export interface LocalizedList {
  pt: string[]
  en: string[]
}

/* ------------------------------------------------------------------ SVG */

export const SVG_TAGS = ['path', 'circle', 'ellipse', 'rect', 'line', 'polyline', 'polygon'] as const
export type SvgTag = (typeof SVG_TAGS)[number]

/**
 * Role of a shape in the derived styles (`data-part` in the source file):
 * - line: a plain stroke in every style (the default).
 * - body: a closed silhouette. Filled in Solid, tinted in Duotone.
 * - cut:  a detail drawn inside a body. A stroke in Outline and Duotone, cut
 *         out of the body (shows the background) in Solid.
 * - slash: a line that crosses a body ("eye-off"). In Solid it opens a wider
 *         gap in the body and is drawn inside it, so it stays visible.
 */
export type NodePart = 'line' | 'body' | 'cut' | 'slash'

/** One shape of a drawing: tag, geometry attributes and role. */
export interface IconNode {
  tag: SvgTag
  attrs: Record<string, string>
  part: NodePart
}

/** Compact form stored in the generated shards: [tag, attrs, part]. 0 line, 1 body, 2 cut, 3 slash. */
export type PackedNode = [SvgTag, Record<string, string>, 0 | 1 | 2 | 3]

/* --------------------------------------------------------------- styles */

export type StyleId = 'outline' | 'solid' | 'duotone' | 'sharp' | 'rounded' | 'filled'

export interface StyleDef {
  id: StyleId
  name: Localized
  description: string
  /**
   * auto: derived from the master drawing when it has body shapes.
   * manual: only exists where a hand-drawn `<slug>.<style>.svg` file exists.
   */
  derivation: 'master' | 'auto' | 'manual'
  /** Whether the stroke-width control applies. */
  stroked: boolean
}

/* ------------------------------------------------------------ licensing */

export type LicenseId = 'MIT'
export type SourceId = 'glyphos'

/* ----------------------------------------------------------- categories */

export interface SubcategoryDef {
  id: string
  name: Localized
}

export interface CategoryDef {
  id: string
  name: Localized
  /** One or two sentences in Portuguese, shown on the category page and used for SEO. */
  description: string
  /** A representative icon slug from this category, used as its symbol in lists. */
  symbol: string
  subcategories: SubcategoryDef[]
}

/* ---------------------------------------------------------------- icons */

/** Popularity is editorial (see docs/CATALOG.md): 5 essential … 1 niche. */
export type Popularity = 1 | 2 | 3 | 4 | 5

/** What a person writes in src/catalog/metadata/<category>.json for each icon. */
export interface IconMeta {
  /** Stable, opaque and unique ("g" + 7 base-32 chars). Survives renames. Assigned by `catalog:ids`. */
  id: string
  /** Unique kebab-case English name, also the file name and the URL. */
  slug: string
  name: Localized
  subcategory?: string
  /** Other names for the same thing ("lixeira" ↔ "lixo", "cesto"). */
  synonyms: LocalizedList
  /** Related concepts and uses ("excluir", "remover"). */
  tags: LocalizedList
  /** Concept family shared by related drawings ("file" for file, file-plus, file-check). */
  family?: string
  /** For a modifier version (file-plus), the slug of the base drawing (file). */
  variantOf?: string
  /** Former slugs. Old URLs redirect here and search still finds them. */
  aliases?: string[]
  popularity: Popularity
  /** ISO date (yyyy-mm-dd) the icon entered the catalogue. */
  added: string
  updated?: string
  author: string
  source: SourceId
  license: LicenseId
}

/** An icon as the app sees it: metadata plus where it lives and what styles it has. */
export interface IconRecord extends IconMeta {
  category: string
  styles: StyleId[]
}

/** Light entry of the generated manifest (lists, sorting, filters). */
export interface ManifestEntry {
  id: string
  slug: string
  name: Localized
  category: string
  subcategory?: string
  styles: StyleId[]
  popularity: Popularity
  added: string
  family?: string
}

/** One icon inside a generated shard: everything the detail view needs. */
export interface ShardIcon extends IconRecord {
  nodes: PackedNode[]
  /** Hand-drawn styles that replace the derived ones. */
  overrides?: Partial<Record<StyleId, PackedNode[]>>
}

export type Shard = Record<string, ShardIcon>
